#!/bin/sh
set -e

# ==============================================================================
# 🔥 火鸟门户 Web/PHP 生产容器启动钩子 (云原生动态环境配置注入)
# ==============================================================================

DBINFO_FILE="/var/www/html/include/dbinfo.inc.php"

# 如果配置了外部数据库环境变量，则自动注入
if [ -n "$DB_HOST" ]; then
    cat <<EOF > "$DBINFO_FILE"
<?php
// 火鸟云原生数据库连接配置 (Auto-generated by entrypoint)
\$DB_HOST = '${DB_HOST:-10.0.0.10}';
\$DB_NAME = '${DB_NAME:-firebird_manila}';
\$DB_USER = '${DB_USER:-firebird_user}';
\$DB_PASS = '${DB_PASS:-firebirdpassword}';
\$DB_PREFIX = '${DB_PREFIX:-huoniao_}';
\$DB_CHARSET = 'utf-8';
EOF
    chown www-data:www-data "$DBINFO_FILE" 2>/dev/null || true
fi

# 确保目录与缓存写权限
mkdir -p /var/www/html/data/cache /var/www/html/data/templates_c 2>/dev/null || true
chown -R www-data:www-data /var/www/html/data 2>/dev/null || true

# 启动 PHP-FPM
exec "$@"
